package com.arahin

import kotlin.math.abs

// Google Maps' navigation notification carries the maneuver only in its large icon: the text is just
// the distance and the street name. The icon is shrunk to a 16x16 grid of opacity (0..15) and matched
// against icons captured from real Maps notifications, so the result does not depend on screen density.
private const val GRID = 16
// the same icon rendered at other sizes stays within ~70 of itself, two different maneuvers are 349+ apart
private const val MAX_DISTANCE = 160

fun iconSignature(alpha: IntArray, w: Int, h: Int): IntArray = IntArray(GRID * GRID) { i ->
    val cx = i % GRID
    val cy = i / GRID
    var sum = 0
    var n = 0
    for (y in cy * h / GRID until (cy + 1) * h / GRID) for (x in cx * w / GRID until (cx + 1) * w / GRID) {
        sum += alpha[y * w + x]
        n++
    }
    if (n == 0) 0 else sum / n / 16
}

// exit is the roundabout exit counted the way traffic flows: in a 4-arm roundabout 1 = first, 2 = straight on, 3 = third
data class IconMatch(val dir: Char, val exit: Int?)

private class Ref(val match: IconMatch, val sig: IntArray)

private val MIRROR = mapOf('L' to 'R', 'R' to 'L', 'l' to 'r', 'r' to 'l', 'h' to 'j', 'j' to 'h')

// Every icon also stands in for its mirror image: left and right turns, and a roundabout in a country driving on the
// other side, where the same exit number points the other way
private fun ref(dir: Char, hex: String, exit: Int? = null): List<Ref> {
    val sig = IntArray(hex.length) { hex[it].digitToInt(16) }
    val flipped = IntArray(sig.size) { sig[it / GRID * GRID + GRID - 1 - it % GRID] }
    return listOf(Ref(IconMatch(dir, exit), sig), Ref(IconMatch(MIRROR[dir] ?: dir, exit), flipped))
}

