    ref('S', "0000000000000000000000000000000000000006700000000000006ff8000000000006ffff80000000006fdefbf800000000dd1de0ce00000000100de00100000000000de00000000000000de000000000000004500000000000000de000000000000004500000000000000de000000000000000000000000000000000000000"), // depart
    ref('S', "0000000000000000000000000000000000000006700000000000006ff8000000000006ffff80000000006fdefbf800000000dd1de0ce00000000100de00100000000000de00000000000000de00000000000000de00000000000000de00000000000000de00000000000000de000000000000000000000000000000000000000"), // straight
    ref('S', "000000000000000000000003100000000000004fd2000000000004fffe20000000004fefefe200000000fe2fb5fd00000000520fb04400000000002fa0000000000000afa7640000000008fd7677710000006fc1000260000001fd00000000000006f500000000000008f1000000000000000000000000000000000000000000"), // straight-past-branch
    ref('L', "0000000000000000000000000000000000000710000000000000af7000000000000af9000000000000afe7777777400004fffffffffffa00006fe4222223af600007fc0000000fa000008f7000000fa00000050000000fa00000000000000fa00000000000000fa00000000000000fa000000000000000000000000000000000"), // left
    ref('R', "0000000000000000000000000000000000000000007000000000000005fc000000000000007fc00000037777777dfc00009fffffffffff6004fb3222223df80008f2000000bf900008f1000005fa000008f100000050000008f100000000000008f100000000000008f100000000000000000000000000000000000000000000"), // right
    ref('l', "000000000000000000000000000000000000deeeee0000000000effcbb0000000000eff9000000000000ebafa00000000000eb0afb0000000000da00afb00000000000000af700000000000000de000000000000005f600000000000000f900000000000000eb00000000000000eb00000000000000000000000000000000000"), // slight-left
    ref('l', "00000000000000000000000000000000003eeeee90000000003ffebb70000000003fff5000027100003f8ef500277100003f62ef41771000003f502fe771000000000007fb40000000000001fd10000000000000de00000000000000df00000000000000df00000000000000df00000000000000000000000000000000000000"), // keep-left
    ref('r', "0000000000000000000000000000000000000008eeeee50000000006bbeff5000016200003fff500000672004fe7f50000006724fe34f5000000077df303f400000003af80000000000000cf10000000000000de00000000000000dd00000000000000dd00000000000000dd0000000000000000000000000000000000000000"), // keep-right
