    ref('O', "000000000000000000000000000000000008eeeee50000000009ffcbb40000000009ffb0000000000009faf9344100000009f0bfc77720000008f0af70167000000000ec00027200000000fb00027200000000af500670000000002effb73000000000018fb20000000000001f90000000000000000000000000000000000000", exit = 1), // roundabout-exit-1
