    ref('O', "00000000000000000000000000000000000000000000000000179600008a000003ffffd1008fb0000df517fa0009fb003f8000bfccccffb03f80009eddddffb00ee202750007fc0005ffe971006fd100003cf61000ad10000006f300000000000006f300000000000006f3000000000000000000000000000000000000000000", exit = 3), // roundabout-exit-3
    ref('O', "0000000000000000000000000000000000001320000000000007fffc10000000005fd79fd000000000ce0009f500000000ec0005f600000000bf200bf4000000004ff78ff203f4000006fc79fe24f5000001f8006fe6f5000001f80005fff5000001f80599dff5000001f809fffff50000000000000000000000000000000000", exit = 3), // roundabout-exit-3-sharp
).flatten()

fun matchIcon(sig: IntArray): IconMatch? {
    val (best, d) = REFS.map { r -> r to r.sig.indices.sumOf { abs(r.sig[it] - sig[it]) } }.minByOrNull { it.second } ?: return null
    return best.match.takeIf { d <= MAX_DISTANCE }
}
